SPAWN_POINTS = [
    {"x": (r * 7 + 21) % 50, "y": (r * 3 + 21) % 100, "type": ["enemy", "item", "powerup"][r % 3]}
    for r in range(80)
]

WAVES = [
    {"wave": w, "enemies": 5 + w * 2, "delay": 10 - min(w, 8), "boss": w % 5 == 0}
    for w in range(1, 21)
]

def get_map() -> List[List[int]]:
    return LEVEL_MAP_DATA

def get_collision() -> List[List[int]]:
    return COLLISION_MASK

def get_spawns():
    return SPAWN_POINTS

def get_waves():
    return WAVES

def map_size():
    return len(LEVEL_MAP_DATA), len(LEVEL_MAP_DATA[0]) if LEVEL_MAP_DATA else (0, 0)

def export() -> Dict[str, Any]:
    return {
        "pack": PACK_ID,
        "map": LEVEL_MAP_DATA,
        "collision": COLLISION_MASK,
        "spawns": SPAWN_POINTS,
        "waves": WAVES,
    }
